# opaqueId:: URL key. CSPRNG, NOT a friendlyId: crypto.randomBytes(16) base64url.
#   Generated by the create path (deploy-sync / P2 API), NOT by @default.
# declaredId:: The declared webhooks.endpoint.define id (string ref, no relation).
# routingTargets:: Subscribers of this endpoint: StoredWebhookRoutingTarget[] ({ id, type: "task" | "session", ..., filterAst }).
# setupPrompt:: The source's instructions for an AI agent registering this endpoint with the provider.
# signingSecretKey:: SecretReference.key string. Plain String, NO @relation -> no FK to SecretReference.
# manuallyDeactivatedAt:: When an operator disabled the endpoint via the dashboard/API. Null means the declarative sync
#   owns the status: a redeploy that re-declares a previously-removed (auto-deactivated) webhook
#   reactivates it. Non-null means the operator disabled it, so the sync leaves the status alone.
class WebhookEndpoint < ApplicationRecord
  self.table_name = "WebhookEndpoint"
  self.implicit_order_column = "createdAt"

  attribute :id, default: -> { Cuid.generate }
  attribute :endpointTenantId, default: ""
  attribute :endpointExternalRef, default: ""
  attribute :routingTargets, default: -> { JSON.parse("[]") }
  attribute :metadata, default: -> { JSON.parse("{}") }
  attribute :secretProvisioning, default: "either"
  alias_attribute :created_at, :createdAt
  alias_attribute :updated_at, :updatedAt

  enum :environmentType, { production: "PRODUCTION", staging: "STAGING", development: "DEVELOPMENT", preview: "PREVIEW" },
       validate: true
  enum :status, { active: "ACTIVE", inactive: "INACTIVE", deleting: "DELETING" }, default: :active, validate: true

  validates :friendlyId, presence: true, uniqueness: true
  validates :opaqueId, presence: true, uniqueness: true
  validates :organizationId, presence: true
  validates :projectId, presence: true
  validates :runtimeEnvironmentId, presence: true,
                                   uniqueness: { scope: [ :declaredId, :endpointTenantId, :endpointExternalRef ] }
  validates :source, presence: true
  validates :declaredId, presence: true
  validates :verifierArtifact, exclusion: { in: [ nil ] }
end
